diff --git .github/workflows/sfl-pr-review-auto.yml .github/workflows/sfl-pr-review-auto.yml
index 3630979..883f852 100644
--- .github/workflows/sfl-pr-review-auto.yml
+++ .github/workflows/sfl-pr-review-auto.yml
@@ -4,7 +4,9 @@
 name: SFL Codex Review Observer
 run-name: >-
   ${{ github.event_name == 'issue_comment' &&
-      format('SFL Codex comment #{0} request {1}', github.event.issue.number, github.event.comment.id) ||
+      format('SFL Codex comment #{0} {1} {2}', github.event.issue.number,
+      contains(github.event.comment.body, '<!-- sfl-codex-review:head=') && 'request' || 'comment',
+      github.event.comment.id) ||
       format('SFL {0} event', github.event_name) }}

 on:
@@ -120,7 +122,11 @@ jobs:
             const marker = `<!-- sfl-codex-review:head=${currentHead.toLowerCase()};base=${currentBase.toLowerCase()};context=${contextToken} -->`;
             const targetURL = (comment.data.html_url || "").toLowerCase();
             let registered = false;
-            for (let attempt = 0; attempt < 12 && !registered; attempt += 1) {
+            const initiallyAllowed = await requesterAllowed(comment.data.user && comment.data.user.login);
+            // Current writers can be waiting for the CLI status POST. A denied
+            // author gets one historical lookup so withdrawal remains possible.
+            const registrationAttempts = initiallyAllowed ? 12 : 1;
+            for (let attempt = 0; attempt < registrationAttempts && !registered; attempt += 1) {
               const statuses = await github.paginate(
                 github.rest.repos.listCommitStatusesForRef,
                 {owner, repo, ref: currentHead, per_page: 100},
@@ -143,7 +149,7 @@ jobs:
               if (!registered && ![context.payload.comment.body, comment.data.body].some(
                 body => (body || "").includes("<!-- sfl-codex-review:head="),
               )) break;
-              if (!registered && attempt < 11) {
+              if (!registered && attempt + 1 < registrationAttempts) {
                 await new Promise(resolve => setTimeout(resolve, 5000));
               }
             }
@@ -340,7 +346,7 @@ jobs:
             }

             function invalidationRequestCommentId(run, pullNumber) {
-              const match = new RegExp(`^SFL Codex comment #${pullNumber} request ([1-9][0-9]*)$`)
+              const match = new RegExp(`^SFL Codex comment #${pullNumber} (?:request|comment) ([1-9][0-9]*)$`)
                 .exec((run && run.display_title) || "");
               const id = match ? Number(match[1]) : NaN;
               return Number.isSafeInteger(id) ? id : null;
@@ -782,8 +788,15 @@ jobs:
                 // Ignore ordinary comments even from current administrators.
                 // A historically registered author remains entitled to revoke
                 // their evidence, and a current writer may remove that comment.
-                if (registrations.length && (registrations.some(status =>
-                    status.creator.login.toLowerCase() === actor) || await requesterAllowed(actor))) {
+                // The run title preserves marker intent from the event payload,
+                // including a later-erased body. Hold a writer's request before
+                // its CLI registry POST becomes visible. Older rc25 titles lack
+                // this distinction, so their active runs remain conservative.
+                const materializingRequest = run.display_title ===
+                  `SFL Codex comment #${pullNumber} request ${requestId}`;
+                if ((registrations.length && (registrations.some(status =>
+                    status.creator.login.toLowerCase() === actor) || await requesterAllowed(actor))) ||
+                    (materializingRequest && await requesterAllowed(actor))) {
                   authorized.push(run);
                 }
               }

